            pnlKartuNaikDalam.PerformLayout();
            pnlKartuModal.ResumeLayout(false);
            pnlKartuModal.PerformLayout();
            pnlKartuPotensi.ResumeLayout(false);
            pnlKartuPotensiDalam.ResumeLayout(false);
            pnlKartuPotensiDalam.PerformLayout();
            ResumeLayout(false);
        }

